private let prime: UInt64 = 1_099_511_628_211
private func hash(_ seed: UInt64, _ value: UInt64) -> UInt64 { var result = seed; for byte in 0..<8 { result ^= (value >> UInt64(byte * 8)) & 255; result &*= prime }; return result }
@main struct SM64BooInCastleSmoke { static func main() { let hidden = SM64BooInCastleBehavior.update(.init(action: 0, timer: 0, stars: 11, room: 0, distanceToMario: 5000, positionZ: 0, opacity: 255, forwardVelocity: 0, activeDifferentRoom: false, angleToMario: 0, angleToHome: 0)); let appear = SM64BooInCastleBehavior.update(.init(action: 0, timer: 0, stars: 12, room: 1, distanceToMario: 5000, positionZ: 0, opacity: 255, forwardVelocity: 0, activeDifferentRoom: false, angleToMario: 0, angleToHome: 0)); let laugh = SM64BooInCastleBehavior.update(.init(action: 1, timer: 0, stars: 12, room: 1, distanceToMario: 500, positionZ: 0, opacity: 255, forwardVelocity: 4, activeDifferentRoom: false, angleToMario: 123, angleToHome: 0)); let returnBoo = SM64BooInCastleBehavior.update(.init(action: 2, timer: 2, stars: 12, room: 1, distanceToMario: 2000, positionZ: -6000, opacity: 180, forwardVelocity: 31, activeDifferentRoom: true, angleToMario: 0, angleToHome: 77)); precondition(hidden.shouldDelete && !hidden.visible, "castle Boo star gate"); precondition(appear.action == 1 && appear.visible, "castle Boo room appearance"); precondition(laugh.action == 2 && laugh.playLaugh && laugh.opacity == 180, "castle Boo laugh"); precondition(returnBoo.action == 1 && returnBoo.opacity == 160, "castle Boo reset"); var f=offset; for o in [hidden,appear,laugh,returnBoo] { f=hash(f,UInt64(o.action)); f=hash(f,UInt64(o.timer)); f=hash(f,UInt64(o.visible ? 1:0)); f=hash(f,UInt64(bitPattern:Int64(o.opacity))); f=hash(f,UInt64(bitPattern:Int64(o.targetAngle))); f=hash(f,UInt64(o.shouldDelete ? 1:0)); f=hash(f,UInt64(o.playLaugh ? 1:0)); f=hash(f,UInt64(o.forwardVelocity.bitPattern)) }; print(String(format:"booInCastleFingerprint=0x%016llx",f)); print("SM64 Modern boo-in-castle smoke passed") } }
